-- Issue #204 : barème serveur de l'épreuve écrite Bac 2025 (session principale).
-- Idempotente : la ligne est insérée ou mise à jour (voir la migration 0033).
insert into public.sujets_examen_ecrit_baremes (exam_id, titre, duree_min, bareme_total, sections_meta)
values
  ('exam-bac2025-principale-ecrit', 'Bac 2025 (Session Principale) - Épreuve Écrite Systèmes & Technologies de l''Informatique', 180, 20, $json$[{"id":"a-ex1-schema","title":"Partie A, exercice 1 : Interprétation de la base de données (3 pts)","type":"modeling","pointsMax":3.0,"questions":[{"id":"A1-REP","points":1.5,"type":"representation","explanation":"Type_Manif(#codeType, libType) ; Manifestation(#codeManif, nomManif, dateOuv, dateFer, codeType#) ; Halle(#codeHalle, libHalle, nbStandsMax) ; Stand(#codeStand, designation, superficie, etat, codeHalle#) ; Client(#codeCl, nomCl, telCl, emailCl, pays) ; Location(#codeManif#, #codeStand#, dateLoc, prix, codeCl#) ; Evaluation(#codeEval, dateEval, noteAccueil, noteConfort, noteSignal, noteLogistique, codeManif#)."},{"id":"A1-VF-1","points":0.125,"type":"code_analysis","explanation":"Faux : codeType est une clé étrangère simple de Manifestation."},{"id":"A1-VF-2","points":0.125,"type":"code_analysis","explanation":"Vrai : une halle contient plusieurs stands, loués par des clients différents."},{"id":"A1-VF-3","points":0.125,"type":"code_analysis","explanation":"Vrai : la clé de Location est (codeManif, codeStand) ; un même client peut louer le même stand pour deux manifestations."},{"id":"A1-VF-4","points":0.125,"type":"code_analysis","explanation":"Faux : la clé (codeManif, codeStand) autorise une seule location par stand et par manifestation."},{"id":"A1-VF-5","points":0.125,"type":"code_analysis","explanation":"Faux : le seul lien entre un client et une manifestation est la table Location."},{"id":"A1-VF-6","points":0.125,"type":"code_analysis","explanation":"Vrai : plusieurs lignes de Location peuvent porter le même codeCl et le même codeManif avec des stands différents."},{"id":"A1-VF-7","points":0.125,"type":"code_analysis","explanation":"Faux : prix est un attribut de Location, il dépend de la manifestation."},{"id":"A1-MOT-A","points":0.15625,"type":"code_analysis","explanation":"codeHalle référence la clé primaire de Halle : intégrité référentielle."},{"id":"A1-MOT-B","points":0.15625,"type":"code_analysis","explanation":"La clé (codeManif, codeStand) est composée de deux champs."},{"id":"A1-MOT-C","points":0.15625,"type":"code_analysis","explanation":"CHECK (prix > 0) est une contrainte d'intégrité de domaine."},{"id":"A1-MOT-D","points":0.15625,"type":"code_analysis","explanation":"codeCl est une clé étrangère dans Location, mais la clé primaire de Client."}]},{"id":"a-ex2-roles","title":"Partie A, exercice 2 : Interprétation des requêtes (1.5 pt)","type":"code_analysis","pointsMax":1.5,"questions":[{"id":"A2-1","points":0.25,"type":"code_analysis","explanation":"INSERT ajoute un client : rôle f."},{"id":"A2-2","points":0.25,"type":"code_analysis","explanation":"Jointure avec Type_Manif et filtre sur libType : rôle i (le code de type, rôle c, ne nécessiterait pas la jointure)."},{"id":"A2-3","points":0.25,"type":"code_analysis","explanation":"UPDATE du téléphone d'un client dont le code est donné : rôle d."},{"id":"A2-4","points":0.25,"type":"code_analysis","explanation":"LIKE '%3' : le code se termine par 3 : rôle e (rôle a : « contient »)."},{"id":"A2-5","points":0.25,"type":"code_analysis","explanation":"ADD CHECK ajoute une contrainte de domaine : rôle g."},{"id":"A2-6","points":0.25,"type":"code_analysis","explanation":"MODIFY ... DEFAULT change la valeur par défaut : rôle b."}]},{"id":"a-ex3-sql","title":"Partie A, exercice 3 : Manipulation des données de la base (6 pts)","type":"sql","pointsMax":6.0,"questions":[{"id":"A3-Q1","points":0.5,"type":"query","explanation":"Projection simple sur Type_Manif."},{"id":"A3-Q2","points":0.5,"type":"query","explanation":"DATEDIFF(dateFer, dateOuv) donne la durée en jours."},{"id":"A3-Q3","points":0.5,"type":"dml","explanation":"UPDATE Location SET prix = prix * 0.85 WHERE codeManif = 'M0001';"},{"id":"A3-Q4","points":0.5,"type":"query","explanation":"Jointure Client-Location et DISTINCT : un client peut louer plusieurs stands."},{"id":"A3-Q5","points":0.5,"type":"query","explanation":"Jointure Stand-Halle, filtres libHalle et etat = 'L', ORDER BY superficie DESC."},{"id":"A3-Q6","points":0.5,"type":"query","explanation":"Jointure Type_Manif-Manifestation, GROUP BY et COUNT."},{"id":"A3-Q7","points":1.0,"type":"query","explanation":"Jointure Manifestation-Location, SUM(prix) par manifestation et HAVING SUM(prix) > 10000."},{"id":"A3-Q8","points":1.0,"type":"query","explanation":"Sous-requête NOT IN sur les stands loués en 2025."},{"id":"A3-Q9","points":1.0,"type":"query","explanation":"Sous-requête avec MAX(prix) sur Location."}]},{"id":"a-ex4-extension","title":"Partie A, exercice 4 : Extension et modification de la structure (1.5 pt)","type":"modeling","pointsMax":1.5,"questions":[{"id":"A4-Q1","points":0.5,"type":"representation","explanation":"Pays(#codePays, nomPays) et Client(#codeCl, nomCl, telCl, emailCl, codePays#) : le pays devient une table, Client en porte la clé étrangère."},{"id":"A4-R-1","points":0.125,"type":"code_analysis","explanation":"codeManif est porté par Note_Service : une évaluation pourrait concerner plusieurs manifestations, la règle R5 n'est pas respectée."},{"id":"A4-R-2","points":0.125,"type":"code_analysis","explanation":"codeSer est dans Evaluation : une évaluation ne porterait que sur un service, la règle R3 n'est pas respectée."},{"id":"A4-R-3","points":0.125,"type":"code_analysis","explanation":"La note n'est pas attribuée au couple (évaluation, service) : la règle R6 n'est pas respectée."},{"id":"A4-R-4","points":0.125,"type":"code_analysis","explanation":"Service porte codeEval et note : un service ne serait évalué qu'une fois, la règle R4 n'est pas respectée."},{"id":"A4-Q2B","points":0.5,"type":"representation","explanation":"Service(#codeSer, libSer) ; Evaluation(#codeEval, dateEval, codeManif#) ; Note_Service(#codeEval#, #codeSer#, note, commentaire)."}]},{"id":"b-ex1-html-lignes","title":"Partie B, exercice 1 (1) : Numéros de ligne du code HTML (1.5 pt)","type":"code_analysis","pointsMax":1.5,"questions":[{"id":"B1-L-1","points":0.1875,"type":"code_analysis","explanation":"Le bouton de type submit est à la ligne 42."},{"id":"B1-L-2","points":0.1875,"type":"code_analysis","explanation":"<span id=\"total\"> est un conteneur en ligne : ligne 40."},{"id":"B1-L-3","points":0.1875,"type":"code_analysis","explanation":"<meta charset=\"utf-8\"> : ligne 5."},{"id":"B1-L-4","points":0.1875,"type":"code_analysis","explanation":"<link rel=\"stylesheet\" ...> : ligne 7."},{"id":"B1-L-5","points":0.1875,"type":"code_analysis","explanation":"<body onload=\"inconnue()\"> : ligne 10."},{"id":"B1-L-6","points":0.1875,"type":"code_analysis","explanation":"<select> : ligne 15."},{"id":"B1-L-7","points":0.1875,"type":"code_analysis","explanation":"<fieldset> : ligne 12."},{"id":"B1-L-8","points":0.1875,"type":"code_analysis","explanation":"<meta name=\"Description\" ...> : ligne 6."}]},{"id":"b-ex1-html-qcm","title":"Partie B, exercice 1 (2) : Analyse du code HTML (1 pt)","type":"qcm","pointsMax":1.0,"questions":[{"id":"B1-Q2-A","points":0.25,"multiple":false,"correctAnswers":["opt-http"],"explanation":"method vaut GET ou POST ; l'URL est donnée par action."},{"id":"B1-Q2-B","points":0.25,"multiple":false,"correctAnswers":["opt-horiz"],"explanation":"<hr> trace une ligne horizontale de séparation."},{"id":"B1-Q2-C","points":0.25,"multiple":false,"correctAnswers":["opt-plage"],"explanation":"Le curseur range propose une valeur dans l'intervalle min-max."},{"id":"B1-Q2-D","points":0.25,"multiple":false,"correctAnswers":["opt-desc"],"explanation":"alt est le texte alternatif affiché si l'image est indisponible et lu par les lecteurs d'écran."}]},{"id":"b-ex2-css","title":"Partie B, exercice 2 : Analyse du code CSS (1.5 pt)","type":"code_analysis","pointsMax":1.5,"questions":[{"id":"B2-1","points":0.125,"type":"code_analysis","explanation":"Le titre du fieldset est une balise <legend>."},{"id":"B2-2","points":0.125,"type":"code_analysis","explanation":"color : red."},{"id":"B2-3","points":0.125,"type":"code_analysis","explanation":"font-size : 20px."},{"id":"B2-4","points":0.125,"type":"code_analysis","explanation":"font-weight : bolder."},{"id":"B2-5","points":0.125,"type":"code_analysis","explanation":"Le label a class=\"labserv\" : sélecteur de classe .labserv (pas #labserv)."},{"id":"B2-6","points":0.125,"type":"code_analysis","explanation":"text-align : center."},{"id":"B2-7","points":0.125,"type":"code_analysis","explanation":"background-color : yellow (et non color : yellow)."},{"id":"B2-8","points":0.125,"type":"code_analysis","explanation":"border : 3px dashed red (dashed = hachée)."},{"id":"B2-9","points":0.125,"type":"code_analysis","explanation":"width : 150px."},{"id":"B2-10","points":0.125,"type":"code_analysis","explanation":"font-style : italic."},{"id":"B2-11","points":0.125,"type":"code_analysis","explanation":"display : inline-block."},{"id":"B2-12","points":0.125,"type":"code_analysis","explanation":"padding : 5px (marge intérieure)."}]},{"id":"b-ex3-js","title":"Partie B, exercice 3 : Analyse du code JavaScript (2 pts)","type":"code_analysis","pointsMax":2.0,"questions":[{"id":"B3-A-1","points":0.125,"type":"code_analysis","explanation":"checked concerne les cases à cocher, pas une liste déroulante."},{"id":"B3-A-2","points":0.125,"type":"code_analysis","explanation":"selectedIndex == 0 : la première option « Choisir une manifestation » est sélectionnée."},{"id":"B3-A-3","points":0.125,"type":"code_analysis","explanation":"value vaut le texte de l'option sans attribut value : il ne vaut jamais 0 ici."},{"id":"B3-A-4","points":0.125,"type":"code_analysis","explanation":"indexOf est une méthode de chaîne ou de tableau, pas une propriété d'une liste déroulante."},{"id":"B3-B-1","points":0.125,"type":"code_analysis","explanation":"name n'affiche pas d'image."},{"id":"B3-B-2","points":0.125,"type":"code_analysis","explanation":"getElementsByName renvoie une liste et value n'est pas l'image."},{"id":"B3-B-3","points":0.125,"type":"code_analysis","explanation":"src de l'élément d'identifiant idimage affiche l'image N.png."},{"id":"B3-B-4","points":0.125,"type":"code_analysis","explanation":"getElementsByName renvoie une liste d'éléments, pas un élément."},{"id":"B3-C-1","points":0.125,"type":"code_analysis","explanation":"Script valide : le total des quatre notes est calculé et affiché."},{"id":"B3-C-2","points":0.125,"type":"code_analysis","explanation":"Une constante ne peut pas être incrémentée : erreur à i++."},{"id":"B3-C-3","points":0.125,"type":"code_analysis","explanation":"La variable s n'est pas initialisée : erreur à s=s+..."},{"id":"B3-C-4","points":0.125,"type":"code_analysis","explanation":"Script valide : idnote est une constante recréée à chaque tour."},{"id":"B3-ROLE","points":0.5,"type":"code_analysis","explanation":"Appelée au chargement de la page (onload), elle initialise les quatre images de notes à 0.png et les quatre curseurs à 0."}]},{"id":"b-ex4-php","title":"Partie B, exercice 4 : Analyse du code PHP (2 pts)","type":"qcm","pointsMax":2.0,"questions":[{"id":"B4-Q1","points":0.25,"multiple":false,"correctAnswers":["opt-code"],"explanation":"$_POST[\"manif\"] reçoit l'attribut value de l'option sélectionnée : M0003."},{"id":"B4-Q2","points":0.25,"multiple":false,"correctAnswers":["opt-erreur"],"explanation":"total est un <span>, non un champ de formulaire : $_POST[\"total\"] n'existe pas, d'où l'erreur et un total vide."},{"id":"B4-Q3","points":0.25,"multiple":false,"correctAnswers":["opt-indexe"],"explanation":"array(...) sans clés crée un tableau indexé : $note[0] à $note[3]."},{"id":"B4-Q4","points":0.25,"multiple":false,"correctAnswers":["opt-iso"],"explanation":"date('Y-m-d') donne année-mois-jour : 2025-06-10."},{"id":"B4-Q5","points":0.25,"multiple":false,"correctAnswers":["opt-die"],"explanation":"or die(...) arrête le script si la connexion échoue : if (!$con) { die(...); } ; echo n'arrête pas le script et $con reste défini même après échec."},{"id":"B4-Q6","points":0.25,"multiple":false,"correctAnswers":["opt-fetchrow"],"explanation":"mysqli_fetch_row lit un enregistrement du résultat de la sélection ; mysqli_fetch_rows n'existe pas."},{"id":"B4-Q7","points":0.25,"multiple":false,"correctAnswers":["opt-affected"],"explanation":"Après un INSERT, mysqli_affected_rows($con) donne le nombre de lignes ajoutées."},{"id":"B4-Q8","points":0.25,"multiple":false,"correctAnswers":["opt-chaine"],"explanation":"mysqli_error renvoie le message ; mysqli_errno renvoie le code."}]}]$json$::jsonb)
on conflict (exam_id) do update set
  titre = excluded.titre,
  duree_min = excluded.duree_min,
  bareme_total = excluded.bareme_total,
  sections_meta = excluded.sections_meta;
